mapper.select:
select top ${limit}
       id, log_id, cfgid, direction, item_type, op, oa_id, oa_name,
       wx_id, wx_name, parent_id, parent_name, seq, message,
       modedatacreater, modedatacreatedate, modedatacreatetime
from ${syncLogItemTable}


        and log_id = #{logId}


        and cfgid = #{cfgId}


        and item_type = #{itemType}


order by seq, id
